ALTER TABLE mission_definitions ADD COLUMN selection_order BIGSERIAL;
-- Restore the old deterministic seed ordering, independent of UUID or lexical order.
UPDATE mission_definitions SET selection_order=array_position(ARRAY['DAILY_PLAY_1','DAILY_CASUAL_2','DAILY_PLAY_3','DAILY_WIN_1','DAILY_RANKED_2','DAILY_CORRECT_100','DAILY_ACCURACY_90','DAILY_PERFECT_WIN_1','DAILY_CHECK_IN','DAILY_DONATE_GOLD_500','WEEKLY_PLAY_15','WEEKLY_WIN_5','WEEKLY_RANKED_WIN_3','WEEKLY_CORRECT_500','WEEKLY_STREAK_3','WEEKLY_PERFECT_3','WEEKLY_DONATE_GOLD_2000','WEEKLY_DONATE_GEMS_5'],code) WHERE code IN ('DAILY_PLAY_1','DAILY_CASUAL_2','DAILY_PLAY_3','DAILY_WIN_1','DAILY_RANKED_2','DAILY_CORRECT_100','DAILY_ACCURACY_90','DAILY_PERFECT_WIN_1','DAILY_CHECK_IN','DAILY_DONATE_GOLD_500','WEEKLY_PLAY_15','WEEKLY_WIN_5','WEEKLY_RANKED_WIN_3','WEEKLY_CORRECT_500','WEEKLY_STREAK_3','WEEKLY_PERFECT_3','WEEKLY_DONATE_GOLD_2000','WEEKLY_DONATE_GEMS_5');
SELECT setval(pg_get_serial_sequence('mission_definitions','selection_order'),18);
CREATE FUNCTION mission_owner_deleted() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN DELETE FROM mission_instances WHERE owner_id=OLD.id; RETURN OLD; END $$;
CREATE TRIGGER mission_user_deleted AFTER DELETE ON users FOR EACH ROW EXECUTE FUNCTION mission_owner_deleted();
CREATE TRIGGER mission_clan_deleted AFTER DELETE ON clans FOR EACH ROW EXECUTE FUNCTION mission_owner_deleted();
